struct Chan { unsigned char type, num, c2, c3, c4, c5; };
extern struct Chan far chans[];
void far noteoff(int dev, int note);

variants.folded_range:
void far f(void)
{
    int i;
    for (i = 0; chans[i].type; i++) {
        if (chans[i].c3 >= 0 && chans[i].c2)
            noteoff(chans[i].c3, chans[i].c4);
    }
}
void far noteoff(int dev, int note) { }

variants.no_range:
void far f(void)
{
    int i;
    for (i = 0; chans[i].type; i++) {
        if (chans[i].c2)
            noteoff(chans[i].c3, chans[i].c4);
    }
}
void far noteoff(int dev, int note) { }

variants.explicit_local:
void far f(void)
{
    int i;
    unsigned char dev;
    for (i = 0; chans[i].type; i++) {
        dev = chans[i].c3;
        if (chans[i].c2)
            noteoff(dev, chans[i].c4);
    }
}
void far noteoff(int dev, int note) { }
